#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#define AL 26
typedef struct Node { int end; struct Node *ch[AL]; } Node;
Node *newnode(void){ Node *p=(Node*)calloc(1,sizeof(Node)); return p; }
void insert(Node *root, const char *s){
    Node *cur=root;
    for(int i=0;s[i];i++){ int c=s[i]-'a';
        if(!cur->ch[c]) cur->ch[c]=newnode();
        cur=cur->ch[c]; }
    cur->end=1;
}
int search(Node *root, const char *s){
    Node *cur=root;
    for(int i=0;s[i];i++){ int c=s[i]-'a';
        if(!cur->ch[c]) return 0; cur=cur->ch[c]; }
    return cur->end;
}
int main(void){
    Node *root=newnode();
    const char *words[]={"cat","car","dog","do"};
    for(int i=0;i<4;i++) insert(root, words[i]);
    printf("插入: cat, car, dog, do\n");
    printf("查询 car -> %s\n", search(root,"car")?"存在":"不存在");
    printf("查询 ca  -> %s（ca 是 cat/car 的前缀但不是完整单词）\n",
           search(root,"ca")?"存在":"不存在(仅前缀)");
    printf("查询 bat -> %s\n", search(root,"bat")?"存在":"不存在");
    return 0;
}
